const events: string[] = [];
const animation = new Animation({
  duration: 700,
  delay: 100,
  onStart: () => events.push('start'),
  onUpdate: (progress, eased) => {
    element.style.opacity = String(eased);
    element.dataset.progress = String(progress);
  },
  onPause: () => events.push('pause'),
  onResume: () => events.push('resume'),
  onStop: () => events.push('stop'),
  onComplete: () => events.push('complete'),
});

animation.play();

snippets.await:
const animation = new Animation({ duration: 700 });

async function run(): Promise<void> {
  animation.restart();
  try {
    await animation;
    console.log('Animation completed');
  } catch (error) {
    console.error('The animation cycle did not complete', error);
  }
}

void run();

