snippets.keyframesDom:
import { animate } from '@re-code/flux/dom';

const entrance = animate('.card', {
  duration: 500,
  easing: 'easeOutCubic',
  properties: {
    opacity: { from: 0, to: 1, duration: 240 },
    transform: (target, index, total) => {
      const depth = Number(target.getAttribute('data-depth') ?? index);
      return [
        `translateY(${16 + depth * (total > 1 ? 4 : 0)}px) scale(0.96)`,
        'translateY(0px) scale(1)',
      ];
    },
    borderRadius: { values: ['12px', '20px'], duration: 360 },
    filter: {
      keyframes: [
        { value: 'blur(8px)', offset: 0, easing: 'easeOutCubic' },
        { value: 'blur(0px)', offset: 1 },
      ],
      duration: 520,
      delay: 40,
    },
  },
  stagger: (index) => index * 70,
});

entrance.play();
await entrance;
entrance.dispose();

