snippets.gesturePhysics:
import { map } from 'rxjs';
import { pointerGestures$, dragInertia } from '@re-code/flux';

let grabOffset = 0;
const initialHandleOffset = handle.getBoundingClientRect().left
  - container.getBoundingClientRect().left;

const dragSubscription = pointerGestures$(handle, { capturePointer: true }).pipe(
  map((event) => {
    if (event.type === 'down') {
      grabOffset = event.x - handle.getBoundingClientRect().left;
    }
    // Convert the pointer location into the handle's top-left coordinate.
    return { ...event, x: event.x - grabOffset };
  }),
  dragInertia({
    axis: 'x',
    getBounds: () => {
      const rect = container.getBoundingClientRect();
      return { minX: rect.left, maxX: rect.right - handle.getBoundingClientRect().width };
    },
  }),
).subscribe(({ x, vx, phase }) => {
  const origin = container.getBoundingClientRect().left;
  handle.style.transform = `translateX(${x - origin - initialHandleOffset}px)`;
  handle.dataset.phase = phase;
  handle.dataset.velocity = String(vx);
});

// Call on component teardown; pointer capture and listeners are released.
dragSubscription.unsubscribe();

snippets.motionLifecycle:
import { Animation, MotionPreferences, Timeline } from '@re-code/flux';

const preferences = new MotionPreferences();
const entrance = new Animation({
  duration: 320,
  motion: {
    preferences,
    reducedMotion: 'finish',
    pauseWhenHidden: true,
  },
});
entrance.play();

// Or apply a policy to a composed scene instead of each child:
const scene = new Timeline({ motion: { preferences, pauseWhenHidden: true } })
  .add(new Animation({ duration: 320 }));
scene.play();

// In app teardown: removes media-query/document listeners.
preferences.destroy();

