snippets.scrollTrigger:
import { Animation, Timeline } from '@re-code/flux';
import { createScrollTrigger } from '@re-code/flux/dom';

const reveal = new Timeline().add(new Animation({
  duration: 700,
  onUpdate: (progress) => {
    panel.style.opacity = String(progress);
    panel.style.transform = `translateY(${(1 - progress) * 24}px)`;
  },
}));

const trigger = createScrollTrigger(panel, {
  start: 'top 85%',
  end: 'bottom 20%',
  timeline: reveal, // scrubs the timeline to the trigger progress
  onEnter: () => console.log('entered'),
  onLeaveBack: () => console.log('left backwards'),
});

// Call after app-driven layout changes if automatic ResizeObserver refresh is insufficient.
trigger.refresh();
// In component teardown:
trigger.destroy();

